class UserInterfaceComponent {
  constructor(id, label) {
    this.id = id;
    this.label = label;
  }

  // This method defines the abstract concept of 'drawing'
  // Subclasses MUST implement this.
  draw() {
    throw new Error("Method 'draw()' must be implemented by subclasses.");
  }
}

class TextField extends UserInterfaceComponent {
  constructor(id, label, placeholder) {
    super(id, label);
    this.placeholder = placeholder;
  }

  draw() {
    return `<label for="${this.id}">${this.label}:</label><input type="text" id="${this.id}" placeholder="${this.placeholder}">`;
  }
}

class Checkbox extends UserInterfaceComponent {
  constructor(id, label, isChecked) {
    super(id, label);
    this.isChecked = isChecked;
  }

  draw() {
    const checkedAttr = this.isChecked ? 'checked' : '';
    return `<input type="checkbox" id="${this.id}" ${checkedAttr}><label for="${this.id}">${this.label}</label>`;
  }
}

// Example Usage (for testing):
const usernameField = new TextField('username', 'Username', 'Enter your username');
const rememberMeCheckbox = new Checkbox('rememberMe', 'Remember Me', true);

console.log(usernameField.draw());
console.log(rememberMeCheckbox.draw());

